      "explanation": "Vācu valodā vārdu \"del viaje\" Laato tikai venuskaitlī, tāpēc teikumā darbības vārdam jābūt venuskaitļa formā (piemēram, \"ist\", nevis \"sind\"). Latviski tomēr bieži saka «rīsi».",
