        "Por esta razón, saproti valodu, cilvēku,tekstu vai situāciju.",
        "Latviski šeit parasti nevajag \"prast\" vai \"mācēt\" • È biežāk ir können.",
        "Te hablaré de mí. = Es saprotu."
